-- Generated by deploy/build_schema_sql.py from 扫描工程数据库字段说明.md. Review before applying.
-- MySQL 8 / InnoDB / utf8mb4. All business times are stored in UTC.

CREATE TABLE IF NOT EXISTS `probe_task` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `task_name` VARCHAR(256) NOT NULL COMMENT '任务名称',
  `task_desc` VARCHAR(2000) NULL DEFAULT NULL COMMENT '任务描述',
  `task_type` VARCHAR(16) NOT NULL DEFAULT 'ONCE' COMMENT '任务类型：ONCE 为一次性任务（可人工重复执行），PERIODIC 为周期任务；仅表示触发方式，不表示周期计划当前是否启用',
  `lifecycle_status` VARCHAR(32) NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE / DELETE_REQUESTED',
  `param_json` LONGTEXT NOT NULL COMMENT '未来执行使用的扫描参数',
  `concurrency` SMALLINT UNSIGNED NOT NULL DEFAULT 3 COMMENT '页面配置的基础端口扫描 worker 数，映射 Python --parallel-workers；不是文件/来源组数量',
  `schedule_enabled` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '周期计划开关：0=未启用/已停用，1=已启用；仅 PERIODIC 可设为 1，ONCE 固定为 0。停用计划不改变 task_type，也不自动停止已创建运行；由 Java 维护',
  `cron_expression` VARCHAR(128) NULL DEFAULT NULL COMMENT '每月指定日期及时间的 cron 表达式；PERIODIC 启用前必填，ONCE 为空；按 Java 调度组件约定语法校验，时区 Asia/Shanghai',
  `next_run_at` DATETIME(6) NULL DEFAULT NULL COMMENT '下一次计划执行时间，保存 UTC，随计划推进更新。由 Java 在启用/修改计划时计算，并由 Java 调度器在到期处理事务中推进；Python 不更新。停用计划或 ONCE 时为空',
  `last_run_no` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '已分配的最大执行序号',
  `latest_run_id` BIGINT UNSIGNED NULL DEFAULT NULL COMMENT '最近创建的执行记录，不代表最近成功记录',
  `delete_requested_at` DATETIME(6) NULL DEFAULT NULL COMMENT '请求删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_task_schedule` (`schedule_enabled`, `next_run_at`),
  KEY `idx_task_lifecycle` (`lifecycle_status`),
  KEY `idx_task_create` (`create_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='任务定义表';

CREATE TABLE IF NOT EXISTS `probe_task_file` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `task_id` BIGINT UNSIGNED NOT NULL COMMENT '所属任务',
  `original_name` VARCHAR(255) NOT NULL COMMENT '原始文件名，仅用于显示',
  `file_format` VARCHAR(16) NOT NULL DEFAULT 'XLSX' COMMENT '首版仅支持 XLSX',
  `storage_id` VARCHAR(32) NOT NULL DEFAULT 'LOCAL' COMMENT '存储根目录配置标识',
  `relative_path` VARCHAR(1024) NOT NULL COMMENT '原文件相对路径；预登记时可填写服务器预分配位置，不代表实体文件已上传完成',
  `parse_status` VARCHAR(16) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING=等待上传/等待解析，PARSING=原文件完整发布后解析中，READY=原文件/规范化文件/源行/hash 全部发布完成，FAILED=解析失败；任何非 READY 项均阻止启动',
  `row_total` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '解析的数据行数',
  `valid_row_count` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '合法目标行数',
  `invalid_row_count` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '无效目标行数',
  `parsed_relative_path` VARCHAR(1024) NULL DEFAULT NULL COMMENT '规范化源记录文件位置',
  `parsed_hash` CHAR(64) NULL DEFAULT NULL COMMENT '规范化输入文件实际 UTF-8 字节的 SHA-256；READY 前必须写入，并在每次运行 input_snapshot_json.files 中冻结，Python 校验快照/本字段/实际文件三者一致',
  `parse_error_json` LONGTEXT NULL DEFAULT NULL COMMENT '文件或行级错误说明',
  `uploaded_by` BIGINT UNSIGNED NULL DEFAULT NULL COMMENT '上传人',
  `parsed_at` DATETIME(6) NULL DEFAULT NULL COMMENT '解析结束时间',
  PRIMARY KEY (`id`),
  KEY `idx_file_task` (`task_id`),
  KEY `idx_file_parse` (`parse_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='任务输入文件表';

CREATE TABLE IF NOT EXISTS `probe_pending_resource` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `task_id` BIGINT UNSIGNED NOT NULL COMMENT '所属任务',
  `file_id` BIGINT UNSIGNED NOT NULL COMMENT '固定输入文件 ID',
  `start_ip` VARCHAR(45) NULL DEFAULT NULL COMMENT '规范化起始 IP；合法记录必填',
  `end_ip` VARCHAR(45) NULL DEFAULT NULL COMMENT '规范化终止 IP；合法记录必填',
  `ip_version` TINYINT UNSIGNED NULL DEFAULT NULL COMMENT '4 / 6',
  `range_size` DECIMAL(39,0) NULL DEFAULT NULL COMMENT '地址范围规模，用于展开前检查',
  `unit_name` VARCHAR(255) NULL DEFAULT NULL COMMENT '模板中的“使用单位信息”',
  `source_unit` VARCHAR(128) NULL DEFAULT NULL COMMENT '模板中的“来源单位”',
  `province_name` VARCHAR(64) NULL DEFAULT NULL COMMENT '从来源单位等明确企业信息直接解析并规范化的省份名称；有效源行必填，不查询省份 code',
  `operator_name` VARCHAR(64) NULL DEFAULT NULL COMMENT '从明确企业信息直接解析并规范化的运营商名称；有效源行必填，与省份名称共同确定企业，不查询运营商 code',
  `validation_status` VARCHAR(16) NOT NULL COMMENT 'VALID / INVALID',
  `validation_error` VARCHAR(2000) NULL DEFAULT NULL COMMENT '无效原因',
  PRIMARY KEY (`id`),
  KEY `idx_resource_file_valid` (`file_id`, `validation_status`),
  KEY `idx_resource_task` (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='原始目标记录表';

CREATE TABLE IF NOT EXISTS `probe_task_run` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `task_id` BIGINT UNSIGNED NOT NULL COMMENT '所属任务',
  `run_no` BIGINT UNSIGNED NOT NULL COMMENT '任务内执行序号',
  `trigger_type` VARCHAR(16) NOT NULL COMMENT 'MANUAL：一次性任务人工启动/再次执行；SCHEDULED：周期任务到期触发',
  `input_snapshot_json` LONGTEXT NOT NULL COMMENT '固定文件 ID 清单、规范化输入 parsed_hash、输入范围及来源摘要；不包含输入版本号或原文件 file_hash',
  `param_snapshot_json` LONGTEXT NOT NULL COMMENT '本次实际扫描参数',
  `rule_snapshot_json` LONGTEXT NULL DEFAULT NULL COMMENT 'Java 下发时可与 rule_hash 同时留空；Python 首次 PREPARING 按部署配置的已发布默认规则补齐完整快照；实际扫描前必须冻结，之后不可替换',
  `rule_hash` CHAR(64) NULL DEFAULT NULL COMMENT '与 rule_snapshot_json 同时提供或同时为空；Python 校验/补齐规则内容 UTF-8 字节的 SHA-256，实际扫描前必备，冻结后恢复复用',
  `scanner_version` VARCHAR(128) NULL DEFAULT NULL COMMENT 'Java 可指定或留空；Python 校验指定版本，未指定时在首次准备阶段记录实际固定部署版本/提交标识，实际扫描前必备；恢复/接管不得静默换版本',
  `concurrency` SMALLINT UNSIGNED NOT NULL DEFAULT 3 COMMENT '本次固定的基础端口扫描 worker 数，等于 param_snapshot_json.port_scan.parallel_workers',
  `status` VARCHAR(32) NOT NULL DEFAULT 'QUEUED' COMMENT '本次实际执行状态',
  `worker_id` VARCHAR(128) NULL DEFAULT NULL COMMENT '当前执行器标识',
  `lease_epoch` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '每次领取/接管递增的租约代次',
  `heartbeat_at` DATETIME(6) NULL DEFAULT NULL COMMENT '最近心跳',
  `lease_expires_at` DATETIME(6) NULL DEFAULT NULL COMMENT '租约到期时间',
  `requested_action` VARCHAR(16) NULL DEFAULT NULL COMMENT 'Java 下发给 Python 的运行控制动作：PAUSE=暂停，RESUME=暂停后恢复，STOP=停止；无控制请求时为空。允许保留最后一次动作，不表示实际执行状态；Python 仅在 request_seq > ack_seq 时处理。新扫描通过新增 status=QUEUED 的运行启动，不使用 START 动作；Java 不用此字段直接修改实际 status',
  `request_seq` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '本 run_id 内单调递增的控制请求序号，由 Java 在锁定任务和运行的控制事务中分配；每个新请求加 1，并与 requested_action、requested_at 同事务写入，恢复不重置。同一动作尚待确认时重试复用原序号；其他待确认动作不允许覆盖，STOP 可覆盖待确认 PAUSE/RESUME 并递增序号。Python 通过 request_seq > ack_seq 判断有待处理请求，完成后将 ack_seq 更新为实际处理的序号，不能直接确认读取后才出现的新请求',
  `ack_seq` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '已确认控制序号，Python 写',
  `requested_at` DATETIME(6) NULL DEFAULT NULL COMMENT '控制请求时间',
  `source_total` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '来源组总数；发布首次启动的事务中必须等于 input_snapshot_json.files 完整清单数量，包含尚未开始执行的文件',
  `source_finished` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '已结束来源组数',
  `host_total` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '各来源组主机数之和',
  `host_finished` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '已处理结束的主机数',
  `unique_ip_count` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '跨来源组去重后的 IP 数',
  `endpoint_total` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '各来源组端点总数',
  `endpoint_finished` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '已处理结束的端点数',
  `progress_percent` DECIMAL(5,2) NOT NULL DEFAULT 0 COMMENT '本次运行整体工作完成百分比，由 Python 汇总各来源组、阶段后写入，Java 直接读取；不能用当前来源组或当前阶段的百分比代替',
  `result_version` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '系统结果提交版本，用于绑定导出文件',
  `workspace_relative_path` VARCHAR(1024) NULL DEFAULT NULL COMMENT '保留的可空兼容字段；NULL 时 Python 按 tasks/{task_id}/runs/{id} 推导运行目录，Java 可显式填写相同值；非空值必须与推导值一致，本次不删除该字段',
  `final_artifact_id` BIGINT UNSIGNED NULL DEFAULT NULL COMMENT '默认最终 XLSX 的产物 ID',
  `summary_json` LONGTEXT NULL DEFAULT NULL COMMENT '分类统计、错误数量、阶段摘要',
  `error_code` VARCHAR(64) NULL DEFAULT NULL COMMENT '运行级错误码',
  `error_message` VARCHAR(2000) NULL DEFAULT NULL COMMENT '运行级错误摘要',
  `started_at` DATETIME(6) NULL DEFAULT NULL COMMENT '首次实际扫描启动发布时间，不是领取时间；Python 完成全部来源组登记后，与 source_total、status=RUNNING 在同一事务首次写入；首次启动前的 PREPARING 期间为空，恢复不重写',
  `finished_at` DATETIME(6) NULL DEFAULT NULL COMMENT '进入终态的时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_run_no` (`task_id`, `run_no`),
  KEY `idx_run_claim` (`status`, `create_date`),
  KEY `idx_run_lease` (`status`, `lease_expires_at`),
  KEY `idx_run_task_time` (`task_id`, `create_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='任务执行记录表';

CREATE TABLE IF NOT EXISTS `probe_run_source` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `task_id` BIGINT UNSIGNED NOT NULL COMMENT '所属任务',
  `run_id` BIGINT UNSIGNED NOT NULL COMMENT '所属执行',
  `file_id` BIGINT UNSIGNED NOT NULL COMMENT '固定的固定输入文件',
  `source_order` INT UNSIGNED NOT NULL COMMENT '文件在本次执行中的顺序',
  `source_name` VARCHAR(255) NOT NULL COMMENT '来源组显示名称，通常为文件名',
  `input_snapshot_json` LONGTEXT NOT NULL COMMENT '该组源记录与归属快照',
  `input_hash` CHAR(64) NOT NULL COMMENT '该组规范化输入校验值',
  `status` VARCHAR(32) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING / RUNNING / PAUSED / SUCCESS / PARTIAL / FAILED / STOPPED；预登记全部来源组时为 PENDING，尚未执行不代表来源组缺失',
  `current_stage` VARCHAR(32) NULL DEFAULT NULL COMMENT '本来源组当前阶段代码，由 Python 更新；主要供任务详情展示，应结合来源组名称及企业归属理解，不代表整个任务或运行的所有企业都处于此阶段',
  `policy_code` VARCHAR(64) NULL DEFAULT NULL COMMENT 'V7 来源扫描策略代码',
  `policy_summary_json` LONGTEXT NULL DEFAULT NULL COMMENT '阈值、单 IP 数、小范围扩展数等',
  `host_total` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '本组去重主机数',
  `host_finished` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '本组已结束主机数',
  `endpoint_total` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '本组端点总数',
  `endpoint_finished` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '本组已结束端点数',
  `progress_percent` DECIMAL(5,2) NOT NULL DEFAULT 0 COMMENT '本组完成百分比',
  `workspace_relative_path` VARCHAR(1024) NOT NULL COMMENT '本组独立目录',
  `error_code` VARCHAR(64) NULL DEFAULT NULL COMMENT '本组错误码',
  `error_message` VARCHAR(2000) NULL DEFAULT NULL COMMENT '本组错误摘要',
  `started_at` DATETIME(6) NULL DEFAULT NULL COMMENT '本来源组实际开始处理时间；仅预登记时为空，不随运行首次启动统一填写',
  `finished_at` DATETIME(6) NULL DEFAULT NULL COMMENT '结束时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_run_file` (`run_id`, `file_id`),
  KEY `idx_source_run_status` (`run_id`, `status`),
  KEY `idx_source_task` (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='执行来源组表';

CREATE TABLE IF NOT EXISTS `probe_run_stage` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `task_id` BIGINT UNSIGNED NOT NULL COMMENT '所属任务',
  `run_id` BIGINT UNSIGNED NOT NULL COMMENT '所属执行',
  `source_group_id` BIGINT UNSIGNED NOT NULL COMMENT '所属来源组',
  `stage_code` VARCHAR(32) NOT NULL COMMENT '阶段代码',
  `stage_order` SMALLINT UNSIGNED NOT NULL COMMENT '阶段顺序',
  `status` VARCHAR(16) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING / RUNNING / PAUSED / SUCCESS / PARTIAL / FAILED / SKIPPED',
  `attempt_no` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '阶段启动/恢复次数',
  `work_unit` VARCHAR(16) NOT NULL COMMENT 'IP / ENDPOINT / FILE / ITEM',
  `work_total` BIGINT UNSIGNED NULL DEFAULT NULL COMMENT '待统计时为空',
  `work_finished` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '已结束工作项',
  `work_success` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '成功数',
  `work_failed` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '失败数',
  `work_skipped` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '跳过数',
  `last_committed_seq` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '最新已入库的阶段提交序号',
  `checkpoint_relative_path` VARCHAR(1024) NULL DEFAULT NULL COMMENT '检查点位置',
  `summary_json` LONGTEXT NULL DEFAULT NULL COMMENT '阶段统计、子阶段信息',
  `error_code` VARCHAR(64) NULL DEFAULT NULL COMMENT '错误码',
  `error_message` VARCHAR(2000) NULL DEFAULT NULL COMMENT '错误摘要',
  `started_at` DATETIME(6) NULL DEFAULT NULL COMMENT '首次开始时间',
  `finished_at` DATETIME(6) NULL DEFAULT NULL COMMENT '完成或失败时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_source_stage` (`run_id`, `source_group_id`, `stage_code`),
  KEY `idx_stage_status` (`run_id`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='阶段执行表';

CREATE TABLE IF NOT EXISTS `probe_host` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `task_id` BIGINT UNSIGNED NOT NULL COMMENT '所属任务',
  `run_id` BIGINT UNSIGNED NOT NULL COMMENT '所属执行',
  `source_group_id` BIGINT UNSIGNED NOT NULL COMMENT '所属来源组',
  `host_ip` VARCHAR(45) NOT NULL COMMENT '规范化 IP',
  `ip_version` TINYINT UNSIGNED NOT NULL COMMENT '4 / 6',
  `source_form` VARCHAR(16) NOT NULL COMMENT 'SINGLE / RANGE / BOTH',
  `scan_mode` VARCHAR(32) NULL DEFAULT NULL COMMENT 'PN / HOST_DISCOVERY',
  `host_phase` VARCHAR(32) NOT NULL DEFAULT 'PENDING_SCAN' COMMENT '当前主机处理阶段',
  `scan_status` VARCHAR(64) NULL DEFAULT NULL COMMENT '实际扫描状态或 V7 原始状态',
  `open_ports_json` LONGTEXT NULL DEFAULT NULL COMMENT '开放端口快照',
  `full_port_status` VARCHAR(32) NULL DEFAULT NULL COMMENT '全端口复查状态；未选中时为空',
  `probe_info` VARCHAR(1000) NULL DEFAULT NULL COMMENT '无开放端口、不可达等说明',
  `error_code` VARCHAR(64) NULL DEFAULT NULL COMMENT '程序执行错误',
  `error_message` VARCHAR(2000) NULL DEFAULT NULL COMMENT '错误摘要',
  `scan_start_time` DATETIME(6) NULL DEFAULT NULL COMMENT '基础端口扫描开始时间',
  `scan_end_time` DATETIME(6) NULL DEFAULT NULL COMMENT '基础端口扫描结束时间',
  `finished_at` DATETIME(6) NULL DEFAULT NULL COMMENT '所有关联识别/复核结束时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_source_host` (`run_id`, `source_group_id`, `host_ip`),
  KEY `idx_host_run_ip` (`run_id`, `host_ip`),
  KEY `idx_host_phase` (`source_group_id`, `host_phase`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='主机过程表';

