CREATE TABLE IF NOT EXISTS `probe_endpoint` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `task_id` BIGINT UNSIGNED NOT NULL COMMENT '所属任务',
  `run_id` BIGINT UNSIGNED NOT NULL COMMENT '所属执行',
  `source_group_id` BIGINT UNSIGNED NOT NULL COMMENT '所属来源组',
  `host_id` BIGINT UNSIGNED NOT NULL COMMENT '所属主机',
  `host_ip` VARCHAR(45) NOT NULL COMMENT '规范化 IP',
  `port` SMALLINT UNSIGNED NOT NULL COMMENT 'TCP 端口',
  `discovered_stage` VARCHAR(32) NOT NULL COMMENT 'PORT_SCAN / FULL_PORT',
  `protocol` VARCHAR(16) NULL DEFAULT NULL COMMENT 'HTTP / HTTPS / NON_HTTP；尚未识别为空',
  `probe_shape` VARCHAR(16) NOT NULL DEFAULT 'UNKNOWN' COMMENT 'FRAMEWORK / WEB / UNKNOWN',
  `endpoint_status` VARCHAR(16) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING / RUNNING / DONE / FAILED / SKIPPED',
  `current_stage` VARCHAR(32) NULL DEFAULT NULL COMMENT '当前识别/复核阶段',
  `scan_status` VARCHAR(64) NULL DEFAULT NULL COMMENT 'V7 的具体探测状态',
  `error_code` VARCHAR(64) NULL DEFAULT NULL COMMENT '执行错误码',
  `error_message` VARCHAR(2000) NULL DEFAULT NULL COMMENT '执行错误摘要',
  `probe_start_time` DATETIME(6) NULL DEFAULT NULL COMMENT '首次识别时间',
  `probe_end_time` DATETIME(6) NULL DEFAULT NULL COMMENT '基础识别结束时间',
  `finished_at` DATETIME(6) NULL DEFAULT NULL COMMENT '全部端点处理结束时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_source_endpoint` (`run_id`, `source_group_id`, `host_ip`, `port`),
  KEY `idx_endpoint_host` (`host_id`),
  KEY `idx_endpoint_status` (`source_group_id`, `endpoint_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='端点过程表';

CREATE TABLE IF NOT EXISTS `probe_asset_port` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `task_id` BIGINT UNSIGNED NOT NULL COMMENT '所属任务',
  `run_id` BIGINT UNSIGNED NOT NULL COMMENT '所属执行',
  `source_group_id` BIGINT UNSIGNED NOT NULL COMMENT '所属来源组',
  `endpoint_id` BIGINT UNSIGNED NOT NULL COMMENT '端点 ID',
  `host_ip` VARCHAR(45) NOT NULL COMMENT 'IP',
  `port` SMALLINT UNSIGNED NOT NULL COMMENT '端口',
  `protocol` VARCHAR(16) NULL DEFAULT NULL COMMENT '已识别协议',
  `is_llm` VARCHAR(16) NOT NULL COMMENT 'CONFIRMED / SUSPECTED / NO',
  `service_type` VARCHAR(64) NULL DEFAULT NULL COMMENT 'V7 服务类型',
  `model_domain` VARCHAR(128) NULL DEFAULT NULL COMMENT '模型领域原始值',
  `deploy_tool` VARCHAR(128) NULL DEFAULT NULL COMMENT '部署工具',
  `deploy_version` VARCHAR(128) NULL DEFAULT NULL COMMENT '工具版本',
  `model_info` LONGTEXT NULL DEFAULT NULL COMMENT '模型信息',
  `gpu_likelihood` VARCHAR(16) NOT NULL DEFAULT 'UNKNOWN' COMMENT 'HIGH / MEDIUM / LOW / UNKNOWN',
  `gpu_evidence` LONGTEXT NULL DEFAULT NULL COMMENT 'GPU 判断证据',
  `gpu_probe_detail_json` LONGTEXT NULL DEFAULT NULL COMMENT 'GPU 探测明细',
  `npu_likelihood` VARCHAR(16) NOT NULL DEFAULT 'UNKNOWN' COMMENT 'HIGH / MEDIUM / LOW / UNKNOWN',
  `npu_evidence` LONGTEXT NULL DEFAULT NULL COMMENT 'NPU 判断证据',
  `accelerator_type` VARCHAR(64) NULL DEFAULT NULL COMMENT 'V7 加速器类型',
  `scan_status` VARCHAR(64) NULL DEFAULT NULL COMMENT '原始扫描结论状态',
  `scan_confidence` VARCHAR(64) NULL DEFAULT NULL COMMENT 'V7 原始置信度',
  `protocol_probe_detail_json` LONGTEXT NULL DEFAULT NULL COMMENT '协议探测明细',
  `http_probe_detail_json` LONGTEXT NULL DEFAULT NULL COMMENT 'HTTP 探测明细',
  `certificate_names_json` LONGTEXT NULL DEFAULT NULL COMMENT '证书域名列表',
  `tested_hostnames_json` LONGTEXT NULL DEFAULT NULL COMMENT '测试域名列表',
  `selected_hostname` VARCHAR(255) NULL DEFAULT NULL COMMENT '最终使用域名',
  `evidence` LONGTEXT NULL DEFAULT NULL COMMENT '原始证据摘要',
  `links_json` LONGTEXT NULL DEFAULT NULL COMMENT '访问链接列表',
  `analysis` LONGTEXT NULL DEFAULT NULL COMMENT 'V7 的“分析”字段',
  `gpu_second_stage_status` VARCHAR(64) NULL DEFAULT NULL COMMENT 'GPU 二阶段复核状态',
  `active_probe_status` VARCHAR(64) NULL DEFAULT NULL COMMENT '主动复核状态，包括 UNKNOWN_INTERRUPTED',
  `gpu_likelihood_before` VARCHAR(16) NULL DEFAULT NULL COMMENT '主动复核前 GPU 结论',
  `gpu_likelihood_after` VARCHAR(16) NULL DEFAULT NULL COMMENT '主动复核后 GPU 结论',
  `verdict_rule_json` LONGTEXT NULL DEFAULT NULL COMMENT '有实际记录时保存命中规则；不得反推伪造',
  `fingerprint_json` LONGTEXT NULL DEFAULT NULL COMMENT '指纹摘要',
  `raw_result_json` LONGTEXT NOT NULL COMMENT '本阶段完整 V7 原始行，保留扩展字段',
  `result_stage_code` VARCHAR(32) NOT NULL COMMENT '最新结果来源阶段',
  `result_stage_seq` BIGINT UNSIGNED NOT NULL COMMENT '最新阶段提交序号',
  `revision_no` BIGINT UNSIGNED NOT NULL DEFAULT 1 COMMENT '本端点系统结果修订号',
  `result_hash` CHAR(64) NOT NULL COMMENT '规范化结果校验值',
  `detect_time` DATETIME(6) NOT NULL COMMENT '当前结果对应检测时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_asset_endpoint` (`endpoint_id`),
  UNIQUE KEY `uk_asset_scope` (`run_id`, `source_group_id`, `host_ip`, `port`),
  KEY `idx_asset_gpu` (`run_id`, `gpu_likelihood`),
  KEY `idx_asset_npu` (`run_id`, `npu_likelihood`),
  KEY `idx_asset_detect` (`run_id`, `detect_time`),
  KEY `idx_asset_tool` (`run_id`, `deploy_tool`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='当前系统结果表';

CREATE TABLE IF NOT EXISTS `probe_asset_port_history` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `task_id` BIGINT UNSIGNED NOT NULL COMMENT '所属任务',
  `run_id` BIGINT UNSIGNED NOT NULL COMMENT '所属执行',
  `source_group_id` BIGINT UNSIGNED NOT NULL COMMENT '所属来源组',
  `asset_port_id` BIGINT UNSIGNED NOT NULL COMMENT '当前结果 ID',
  `revision_no` BIGINT UNSIGNED NOT NULL COMMENT '端点修订号',
  `stage_code` VARCHAR(32) NOT NULL COMMENT '修订来源阶段',
  `stage_seq` BIGINT UNSIGNED NOT NULL COMMENT '阶段提交序号',
  `event_id` CHAR(36) NOT NULL COMMENT '产生修订的提交事件',
  `change_reason` VARCHAR(128) NOT NULL COMMENT 'INITIAL / GPU_CORRELATION / NPU_CORRELATION / GPU_RECHECK / ACTIVE_RECHECK 等',
  `result_snapshot_json` LONGTEXT NOT NULL COMMENT '完整规范化结果及原始 V7 行',
  `result_hash` CHAR(64) NOT NULL COMMENT '快照校验值',
  `detect_time` DATETIME(6) NOT NULL COMMENT '对应检测时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_asset_revision` (`asset_port_id`, `revision_no`),
  KEY `idx_history_run` (`run_id`),
  KEY `idx_history_event` (`event_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统结果修订历史表';

CREATE TABLE IF NOT EXISTS `probe_scan_event` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `event_id` CHAR(36) NOT NULL COMMENT '全局唯一事件 ID',
  `schema_version` SMALLINT UNSIGNED NOT NULL DEFAULT 1 COMMENT '提交记录格式版本',
  `task_id` BIGINT UNSIGNED NOT NULL COMMENT '所属任务',
  `run_id` BIGINT UNSIGNED NOT NULL COMMENT '所属执行',
  `source_group_id` BIGINT UNSIGNED NULL DEFAULT NULL COMMENT '来源组事件必填；运行级产物事件可空',
  `stage_code` VARCHAR(32) NOT NULL COMMENT '阶段代码',
  `stage_seq` BIGINT UNSIGNED NOT NULL COMMENT '阶段内提交序号',
  `event_type` VARCHAR(32) NOT NULL COMMENT '阶段、主机、端点、结果、修订或产物事件',
  `lease_epoch` BIGINT UNSIGNED NOT NULL COMMENT '本次提交所用租约代次',
  `payload_hash` CHAR(64) NOT NULL COMMENT '业务内容校验值',
  `payload_relative_path` VARCHAR(1024) NULL DEFAULT NULL COMMENT '对应不可变本地提交记录',
  `record_count` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '本次提交的记录数',
  `committed_at` DATETIME(6) NOT NULL COMMENT '数据库提交时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_event` (`event_id`),
  KEY `idx_event_stage` (`run_id`, `source_group_id`, `stage_code`, `stage_seq`),
  KEY `idx_event_task` (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='已提交事件表';

CREATE TABLE IF NOT EXISTS `probe_artifact` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `task_id` BIGINT UNSIGNED NOT NULL COMMENT '所属任务',
  `run_id` BIGINT UNSIGNED NOT NULL COMMENT '所属执行',
  `source_group_id` BIGINT UNSIGNED NULL DEFAULT NULL COMMENT '来源组产物关联；汇总产物为空',
  `scope_type` VARCHAR(16) NOT NULL COMMENT 'RUN / SOURCE',
  `scope_id` BIGINT UNSIGNED NOT NULL COMMENT '对应 run_id 或 source_group_id',
  `artifact_type` VARCHAR(32) NOT NULL COMMENT '产物类型',
  `logical_name` VARCHAR(128) NOT NULL COMMENT '稳定逻辑名称，如 final_xlsx、port_cache',
  `generation_no` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT '文件生成版本',
  `display_name` VARCHAR(255) NOT NULL COMMENT '下载显示名称',
  `storage_id` VARCHAR(32) NOT NULL DEFAULT 'LOCAL' COMMENT '存储配置标识',
  `relative_path` VARCHAR(1024) NOT NULL COMMENT '相对存储根目录的路径',
  `mime_type` VARCHAR(128) NULL DEFAULT NULL COMMENT '文件媒体类型',
  `file_size` BIGINT UNSIGNED NULL DEFAULT NULL COMMENT '文件大小',
  `file_hash` CHAR(64) NULL DEFAULT NULL COMMENT '完成文件的校验值',
  `status` VARCHAR(16) NOT NULL DEFAULT 'WRITING' COMMENT 'WRITING / READY / FAILED',
  `stage_code` VARCHAR(32) NOT NULL COMMENT '生成阶段',
  `endpoint_id` BIGINT UNSIGNED NULL DEFAULT NULL COMMENT '端点证据关联',
  `result_revision_no` BIGINT UNSIGNED NULL DEFAULT NULL COMMENT '截图对应的系统结果修订',
  `result_version` BIGINT UNSIGNED NULL DEFAULT NULL COMMENT '报告对应的运行结果版本',
  `source_url` LONGTEXT NULL DEFAULT NULL COMMENT '证据采集地址',
  `captured_at` DATETIME(6) NULL DEFAULT NULL COMMENT '证据采集时间',
  `metadata_json` LONGTEXT NULL DEFAULT NULL COMMENT '截图方式、统计、关联信息等',
  `error_message` VARCHAR(2000) NULL DEFAULT NULL COMMENT '生成失败摘要',
  `ready_at` DATETIME(6) NULL DEFAULT NULL COMMENT '文件发布完成时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_artifact_version` (`scope_type`, `scope_id`, `artifact_type`, `logical_name`, `generation_no`),
  KEY `idx_artifact_run` (`run_id`, `artifact_type`, `status`),
  KEY `idx_artifact_endpoint` (`endpoint_id`),
  KEY `idx_artifact_task` (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='扫描产物表';

CREATE TABLE IF NOT EXISTS `probe_task_cleanup_job` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `task_id` BIGINT UNSIGNED NOT NULL COMMENT '要删除的任务 ID',
  `request_id` CHAR(36) NOT NULL COMMENT '删除请求去重 ID',
  `status` VARCHAR(32) NOT NULL DEFAULT 'WAIT_STOP' COMMENT '清理作业状态',
  `storage_id` VARCHAR(32) NOT NULL DEFAULT 'LOCAL' COMMENT '任务目录所在存储配置',
  `task_relative_path` VARCHAR(1024) NOT NULL COMMENT '由 task_id 派生的任务根目录',
  `worker_id` VARCHAR(128) NULL DEFAULT NULL COMMENT '文件清理执行器',
  `lease_epoch` BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '清理租约代次',
  `heartbeat_at` DATETIME(6) NULL DEFAULT NULL COMMENT '清理心跳',
  `lease_expires_at` DATETIME(6) NULL DEFAULT NULL COMMENT '清理租约到期时间',
  `attempt_no` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '清理尝试次数',
  `retry_after` DATETIME(6) NULL DEFAULT NULL COMMENT '可再次尝试的时间',
  `files_purged_at` DATETIME(6) NULL DEFAULT NULL COMMENT '文件清理完成时间',
  `data_purged_at` DATETIME(6) NULL DEFAULT NULL COMMENT '业务数据清理完成时间',
  `requested_by` BIGINT UNSIGNED NULL DEFAULT NULL COMMENT '发起人',
  `last_error_code` VARCHAR(64) NULL DEFAULT NULL COMMENT '最近错误码',
  `last_error_message` VARCHAR(2000) NULL DEFAULT NULL COMMENT '最近错误摘要',
  `finished_at` DATETIME(6) NULL DEFAULT NULL COMMENT '完成时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cleanup_request` (`request_id`),
  UNIQUE KEY `uk_cleanup_task` (`task_id`),
  KEY `idx_cleanup_claim` (`status`, `retry_after`, `lease_expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='任务清理作业表';

CREATE TABLE IF NOT EXISTS `probe_asset_review` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者，即实际复核人；Java 从登录态填写，不接受客户端指定其他用户',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间；Java 写 UTC',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者；追加型复核历史不做 UPDATE，保持 NULL',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间；追加型复核历史不做 UPDATE，保持 NULL',
  `task_id` BIGINT UNSIGNED NOT NULL COMMENT '被复核结果所属任务，须与 asset_port_id 实际归属一致',
  `run_id` BIGINT UNSIGNED NOT NULL COMMENT '被复核结果所属执行；第 n 次通过关联 probe_task_run.run_no 展示，不复制序号',
  `source_group_id` BIGINT UNSIGNED NOT NULL COMMENT '被复核结果所属来源组；同 IP 不同文件的结果仍分别记录',
  `asset_port_id` BIGINT UNSIGNED NOT NULL COMMENT '关联 probe_asset_port.id，是单条复核身份，不以 IP 或端口字符串替代',
  `request_id` CHAR(36) NOT NULL COMMENT '同一任务内一次复核提交的 UUID；超时/断网重试复用原值，主动再次复核使用新值；幂等查询范围为 task_id + request_id',
  `request_hash` CHAR(64) NOT NULL COMMENT 'Java 对登录用户、任务/执行、排序去重的完整 assetIds 及各条期望系统版本/哈希、期望人工版本、动作、规范化说明计算的 SHA-256；不包含请求时间；防止同 UUID 被换内容重用',
  `review_no` BIGINT UNSIGNED NOT NULL COMMENT '本 asset_port_id 内单调递增的人工复核序号，从 1 开始；不是扫描执行序号，也不是系统 revision_no',
  `system_revision_no` BIGINT UNSIGNED NOT NULL COMMENT '提交时复核依据的 probe_asset_port.revision_no，由服务端核验并冻结',
  `system_result_hash` CHAR(64) NOT NULL COMMENT '同一系统结果版本的 result_hash，和 system_revision_no 一起校验依据是否变化',
  `system_gpu_likelihood` VARCHAR(16) NOT NULL COMMENT '当时系统 GPU 结论快照，HIGH / MEDIUM / LOW / UNKNOWN；本版可提交对象仅限系统 MEDIUM',
  `review_action` VARCHAR(16) NOT NULL COMMENT 'MAINTAIN / CONFIRM_HIGH / CONFIRM_MID；分别维持当时系统判定、确认为高、调整为中',
  `reviewed_gpu_likelihood` VARCHAR(16) NOT NULL COMMENT 'Java 派生的人工结论：MAINTAIN 复制当时系统值，CONFIRM_HIGH=HIGH，CONFIRM_MID=MEDIUM；不直接相信客户端传值',
  `review_remark` VARCHAR(2000) NOT NULL COMMENT '复核说明，去首尾空白后非空、最多 2000 字符；即使维持判定也须填写',
  `reviewed_at` DATETIME(6) NOT NULL COMMENT '实际提交复核的 UTC 时间，Java 生成；同一批次各行使用同一时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_review_asset_no` (`asset_port_id`, `review_no`),
  UNIQUE KEY `uk_review_request_asset` (`request_id`, `asset_port_id`),
  KEY `idx_review_run_time` (`run_id`, `reviewed_at`, `id`),
  KEY `idx_review_task_request` (`task_id`, `request_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='人工复核记录表';

CREATE TABLE IF NOT EXISTS `compute_report_batch` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `province_code` VARCHAR(32) NOT NULL COMMENT '组织字典的省份标准码',
  `province_name` VARCHAR(64) NOT NULL COMMENT '规范化省份名称，与扫描源记录采用相同名称解析规则，作为名称比对键的一部分',
  `operator_code` VARCHAR(32) NOT NULL COMMENT '组织字典的运营商标准码',
  `operator_name` VARCHAR(64) NOT NULL COMMENT '规范化运营商名称，与扫描源记录采用相同名称解析规则，作为名称比对键的一部分',
  `enterprise_name` VARCHAR(255) NOT NULL COMMENT '规范化省份＋运营商；原始企业文本保留在上传原文件',
  `report_month` DATE NOT NULL COMMENT '上报月份，保存该月首日，如 2026-10-01，API 返回 2026-10',
  `revision_no` BIGINT UNSIGNED NOT NULL DEFAULT 1 COMMENT '同企业同月完整覆盖成功后加一，内容相同重传不增加',
  `row_count` BIGINT UNSIGNED NOT NULL COMMENT '当前有效清单的 IP 段记录数，不是 IP 展开数',
  `content_hash` CHAR(64) NOT NULL COMMENT '本企业规范化全量明细的 SHA-256；判断同企业同月重复上报是否内容相同：相同返回 UNCHANGED，不替换明细、不递增 revision_no。与原文件是否允许编辑无关，不是整个 XLSX 的文件 hash；由 Java 计算和维护',
  `original_name` VARCHAR(255) NOT NULL COMMENT '当前提交原文件名',
  `relative_path` VARCHAR(1024) NOT NULL COMMENT '原文件相对路径，位于独立 compute-imports 目录，不位于 tasks 目录',
  `imported_at` DATETIME(6) NOT NULL COMMENT '最近实际发布全量清单的时间，保存 UTC；页面上报日期由此转换显示',
  `imported_by` BIGINT UNSIGNED NULL DEFAULT NULL COMMENT '发布人',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_compute_enterprise_month` (`province_code`, `operator_code`, `report_month`),
  KEY `idx_compute_month` (`report_month`, `province_code`, `operator_code`),
  UNIQUE KEY `uk_compute_enterprise_name_month` (`province_name`, `operator_name`, `report_month`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业月份上报批次表';

CREATE TABLE IF NOT EXISTS `compute_ip` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '本表自增主键，PRIMARY KEY',
  `creator` BIGINT(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_date` DATETIME NULL DEFAULT NULL COMMENT '创建时间',
  `updater` BIGINT(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_date` DATETIME NULL DEFAULT NULL COMMENT '更新时间',
  `batch_id` BIGINT UNSIGNED NOT NULL COMMENT '所属 compute_report_batch.id，月份及企业归属以批次为准',
  `enterprise_name` VARCHAR(255) NOT NULL COMMENT '模板“企业名称”去首尾空格并规范化后的企业名称；导入逐行保存，须与所属批次 enterprise_name 一致，不等同于使用人/单位',
  `system_name` VARCHAR(255) NULL DEFAULT NULL COMMENT '模板“系统”，保留原值，不当作扫描状态；业务枚举未定义',
  `house_id` VARCHAR(128) NULL DEFAULT NULL COMMENT '模板“机房ID”，业务字符串，不是 compute_house.id；不要求机房台账存在',
  `segment_id` VARCHAR(128) NULL DEFAULT NULL COMMENT '模板“IP地址段编号”，保留原值，不作为全局唯一键',
  `start_ip` VARCHAR(45) NOT NULL COMMENT '模板“起始IP地址”，规范化 IPv4/IPv6',
  `end_ip` VARCHAR(45) NOT NULL COMMENT '模板“终止IP地址”，同族且不小于起始地址；原值空时按单 IP 规范化',
  `ip_version` TINYINT UNSIGNED NOT NULL COMMENT '4 / 6',
  `start_ip_bin` BINARY(16) NOT NULL COMMENT '范围比较用大端 16 字节；IPv4 高 12 字节补 0，低 4 字节为 IPv4',
  `end_ip_bin` BINARY(16) NOT NULL COMMENT '与起始地址同一编码；必须结合 ip_version 比较',
  `range_size` DECIMAL(39,0) NOT NULL COMMENT '包含两端的地址数；不得为比对展开全量 IPv6 地址',
  `ip_use_type` VARCHAR(64) NULL DEFAULT NULL COMMENT '模板“IP地址使用方式”，保留文本，未确认编码前不强制转旧 0/1/2',
  `use_unit` VARCHAR(255) NULL DEFAULT NULL COMMENT '模板“使用人或者单位”，不等同于上报企业',
  `source_unit` VARCHAR(255) NULL DEFAULT NULL COMMENT '模板“来源单位”',
  `allocation_unit` VARCHAR(255) NULL DEFAULT NULL COMMENT '模板“分配单位”',
  `allocation_time_raw` VARCHAR(128) NULL DEFAULT NULL COMMENT '模板“分配使用时间”的原始展示值',
  `allocation_time` DATETIME(6) NULL DEFAULT NULL COMMENT '能合法解析时保存 UTC；无时区原值按 Asia/Shanghai 解释，不能代替上报时间',
  PRIMARY KEY (`id`),
  KEY `idx_compute_ip_range` (`batch_id`, `ip_version`, `start_ip_bin`),
  KEY `idx_compute_ip_house` (`batch_id`, `house_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业月份全量 IP 明细表';
